import SuperJSON from './index.js';
import { processStackString, processStackFrames } from './error-stack.js';
import { sanitizeMessage } from './error-sanitizer.js';

function matchesErrorMode(v: Error, superJson: SuperJSON, mode: 'string' | 'frames'): boolean {
  const options = superJson.errorStack;
  return !!options && options.mode === mode &&
    (!options.classFilter.length || options.classFilter.includes(v.name));
}

function serializeError(v: Error, superJson: SuperJSON): any {
  const options = superJson.errorStack;
  if (!options) {
    const result: any = { name: v.name, message: v.message };
    if ('cause' in v) result.cause = v.cause;
    superJson.allowedErrorProps.forEach(prop => { result[prop] = (v as any)[prop]; });
    return superJson.errorClassRegistry.getProcessor(v.name)?.(result) ?? result;
  }
  const seen = new Set<Error>();
  function serialize(current: Error, depth: number): any {
    seen.add(current);
    const matches = !options!.classFilter.length || options!.classFilter.includes(current.name);
    const result: any = {
      name: current.name,
      message: matches && options!.sanitizeMessage ? sanitizeMessage(current.message) : current.message,
    };
    superJson.allowedErrorProps.forEach(prop => {
      if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause' && prop !== 'errors') result[prop] = (current as any)[prop];
    });
    if (matches && typeof current.stack === 'string') {
      if (options!.mode === 'string' && superJson.allowedErrorProps.includes('stack')) result.stack = processStackString(current.stack, options!);
      if (options!.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) result.stackFrames = processStackFrames(current.stack, options!);
    }
    if (typeof AggregateError !== 'undefined' && current instanceof AggregateError) result.errors = current.errors;
    const cause = current.cause;
    if (cause instanceof Error && !seen.has(cause) &&
        ((options!.includeCauses === 'direct' && depth === 0) ||
         (options!.includeCauses === 'deep' && depth < options!.maxCauseDepth))) {
      result.cause = serialize(cause, depth + 1);
    }
    return superJson.errorClassRegistry.getProcessor(current.name)?.(result) ?? result;
  }
  return serialize(v, 0);
}

function deserializeError(v: any, superJson: SuperJSON): Error {
  const make = (value: any): Error => {
    const cause = value.cause && !(value.cause instanceof Error) && typeof value.cause === 'object' && 'message' in value.cause ? make(value.cause) : value.cause;
    const e = value.name === 'AggregateError' && typeof AggregateError !== 'undefined'
      ? new AggregateError(value.errors ?? [], value.message, { cause })
      : new Error(value.message, { cause });
    e.name = value.name;
    e.stack = Array.isArray(value.stackFrames) ? value.stackFrames.map((frame: { raw: string }) => frame.raw).join('\n') : value.stack;
    if (Array.isArray(value.stackFrames)) (e as any).stackFrames = value.stackFrames;
    superJson.allowedErrorProps.forEach(prop => {
      if (prop !== 'stackFrames' || !Array.isArray(value.stackFrames)) (e as any)[prop] = value[prop];
    });
    return e;
  };
  return make(v);
}

const simpleRules = [
  simpleTransformation(
    (v, s): v is Error => isError(v) && matchesErrorMode(v, s, 'string'),
    'Error/stack', serializeError, deserializeError
  ),
  simpleTransformation(
    (v, s): v is Error => isError(v) && matchesErrorMode(v, s, 'frames'),
    'Error/frames', serializeError, deserializeError
  ),

(v, superJson) => {
  const baseError: any = {
    name: v.name,
    message: v.message,
  };

  if ('cause' in v) {
    baseError.cause = v.cause;
  }

  superJson.allowedErrorProps.forEach(prop => {
    baseError[prop] = (v as any)[prop];
  });

  return baseError;
},
(v, superJson) => {
  const e = new Error(v.message, { cause: v.cause });
  e.name = v.name;
  e.stack = v.stack;

  superJson.allowedErrorProps.forEach(prop => {
    (e as any)[prop] = v[prop];
  });

  return e;
}
